import heapq

class Grid:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.grid = [['#' for _ in range(width)] for _ in range(height)] 

    def set_wall(self, x, y):
        self.grid[y][x] = '#'

    def is_valid(self, x, y):
        return 0 <= x < self.width and 0 <= y < self.height and self.grid[y][x] != '#'

    def get_neighbors(self, x, y):
        neighbors = []
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if self.is_valid(nx, ny):
                neighbors.append((nx, ny))
        return neighbors


def breadth_first_search(grid, start, end):
    """
    Performs breadth-first search to find the path from start to end.

    Args:
        grid: The grid representation of the environment.
        start: The starting position (x, y).
        end: The ending position (x, y).

    Returns:
        A list of tuples representing the path from start to end, 
        or None if no path exists.
    """

    open_set = [(0, start)]
    closed_set = set()
    came_from = {}
    g_score = {}
    h_score = {}

    # Calculate heuristic score
    for x in range(grid.width):
        for y in range(grid.height):
            h_score[(x, y)] = abs(x - end[0]) + abs(y - end[1]) 

    # Breadth-first search loop
    while open_set:
        queue_len, current = heapq.heappop(open_set)

        if current == end:
            path = []
            while current:
                path.append(current)
                current = came_from.get(current)
            return path[::-1]  # Reverse the path

        closed_set.add(current)

        for neighbor in grid.get_neighbors(current[0], current[1]):
            if neighbor in closed_set:
                continue

            new_g_score = g_score.get(current, 0) + 1 

            if neighbor not in open_set:
                heapq.heappush(open_set, (new_g_score + h_score[neighbor], neighbor))
                came_from[neighbor] = current
                g_score[neighbor] = new_g_score

    return None  # No path found



